    private RecipeTransferContext(int transferId, R recipe, RecipeType<R> recipeType, AbstractContainerScreen<C> screen, IRecipeSlotsView recipeSlots, Player player, boolean maxTransfer, BiConsumer<IRecipeTransferContext<R, C>, RecipeTransferResult> completionHandler) {
