            catch (RuntimeException e) {
                LOGGER.error("Recipe transfer listener '{}' threw an error before recipe transfer: ", listener.getClass(), (Object)e);
            }
        }
    }

    public void completeRecipeTransfer(IRecipeTransferContext<?, ?> context, RecipeTransferResult result) {
        ErrorUtil.checkNotNull(context, "context");
        ErrorUtil.checkNotNull(result, "result");
        for (IRecipeTransferListener listener : this.recipeTransferListeners) {
            try {
                listener.afterRecipeTransfer(context, result);
            }
            catch (RuntimeException e) {
                LOGGER.error("Recipe transfer listener '{}' threw an error after recipe transfer: ", listener.getClass(), (Object)e);
            }
        }
    }
}

